import os
import sys
import time
import threading
import queue
from datetime import datetime
from concurrent.futures import ThreadPoolExecutor, as_completed

def process_copy(source_path, destination_dir, log_file):
    try:
        source_file = os.path.join(destination_dir, os.path.basename(source_path))
        with open(source_path, 'rb') as src, open(source_file, 'wb') as dst:
            dst.write(src.read())
        return "OK", len(os.path.getsize(source_path))
    except Exception as e:
        return "FAIL", str(e)

def worker(q, destination_dir, log_file, copied, failed):
    while True:
        source_path = q.get()
        if source_path is None:
            q.task_done()
            break
        status, result = process_copy(source_path, destination_dir, log_file)
        with open(os.path.join(destination_dir, log_file), 'a') as f:
            timestamp = datetime.utcnow().isoformat() + 'Z'
            f.write(f"{timestamp} {source_path} {status} {result}\n")
        if status == "OK":
            with threading.Lock():
                copied[0] += 1
        else:
            with threading.Lock():
                failed[0] += 1
        q.task_done()

def throttled_copy(source_paths, destination_dir):
    log_file = "copy_log.txt"
    copied = [0]
    failed = [0]
    q = queue.Queue()
    threads = []

    for path in source_paths:
        q.put(path)

    with ThreadPoolExecutor(max_workers=3) as executor:
        futures = []
        for _ in range(3):
            t = threading.Thread(target=worker, args=(q, destination_dir, log_file, copied, failed))
            t.start()
            threads.append(t)
            futures.append(executor.submit(lambda: None))  # Dummy submission to start threads

        for future in as_completed(futures):
            pass

    for _ in range(3):
        q.put(None)

    for t in threads:
        t.join()

    # Rate limiting
    start_time = time.time()
    for _ in range(len(source_paths)):
        time.sleep(0.1)
        if time.time() - start_time >= 1:
            start_time = time.time()

    print(f"copied={copied[0]} failed={failed[0]}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python throttled_copy.py <destination_directory>")
        sys.exit(1)

    destination_dir = sys.argv[1]
    source_paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            source_paths.append(line)

    throttled_copy(source_paths, destination_dir)
